INSERT INTO `tag` (`name`, `status`) SELECT 'SC-200', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'SC-200') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft Sentinel', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Microsoft Sentinel') x);
